import Foundation
import zlib
import Testing
import PreviewContracts
import PreviewTestSupport
@testable import PreviewFormats

/// Shared helpers for the data-format adapter tests. Fixtures come from `DataFixtures` (generated by
/// `script/data_fixtures.py`) or are assembled in the test from plain values.
enum DataTest {
    static func context(_ budget: PreviewBudget = PreviewBudget(maxMilliseconds: 30_000)) -> RequestContext {
        RequestContext(budget: budget)
    }

    /// The JSON object of a summary document.
    static func object(_ document: ParsedTextDocument) throws -> [String: Any] {
        let value = try JSONSerialization.jsonObject(with: Data(document.text.utf8))
        return try #require(value as? [String: Any])
    }

    static func table(_ object: [String: Any]) throws -> (columns: [String], rows: [[Any]], truncated: Bool) {
        let table = try #require(object["table"] as? [String: Any])
        let columns = try #require((table["columns"] ?? table["columnNames"]) as? [String])
        let rows = try #require(table["rows"] as? [[Any]])
        return (columns, rows, table["truncated"] as? Bool ?? false)
    }

    /// A table cell's text: strings and joined segments; JSON null reads as "null".
    static func cell(_ value: Any) -> String {
        if let text = value as? String { return text }
        if let parts = value as? [String] { return parts.joined() }
        if value is NSNull { return "null" }
        if let object = value as? [String: Any], let bytes = object["bytes"] { return "bytes:\(bytes)" }
        return "\(value)"
    }

    static func rows(_ object: [String: Any]) throws -> [[String]] {
        try table(object).rows.map { $0.map(cell) }
    }

    /// Parses through the random-access path with an in-memory source.
    static func parse(_ adapter: any RandomAccessFormatAdapter, _ data: Data,
                      budget: PreviewBudget = PreviewBudget(maxMilliseconds: 30_000)) throws -> ParsedTextDocument {
        try adapter.parse(DataByteSource(data), context: context(budget))
    }

    static func parse(_ adapter: any BinaryFormatAdapter, _ data: Data,
                      budget: PreviewBudget = PreviewBudget(maxMilliseconds: 30_000)) throws -> ParsedTextDocument {
        try adapter.parse(FileBytes(data: data), context: context(budget))
    }

    static func little(_ value: UInt64, width: Int) -> Data {
        Data((0..<width).map { UInt8(truncatingIfNeeded: value >> ($0 * 8)) })
    }

    /// Counts JSON nodes the way the native outline does: every key, value and container is one.
    static func nodeCount(_ value: Any) -> Int {
        if let dictionary = value as? [String: Any] { return 1 + dictionary.values.reduce(0) { $0 + nodeCount($1) + 1 } }
        if let array = value as? [Any] { return 1 + array.reduce(0) { $0 + nodeCount($1) } }
        return 1
    }

    /// Raw DEFLATE (RFC 1951), as stored in ZIP members and Avro blocks.
    static func rawDeflate(_ bytes: [UInt8]) -> [UInt8] {
        var stream = z_stream()
        deflateInit2_(&stream, 9, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY, ZLIB_VERSION, Int32(MemoryLayout<z_stream>.size))
        defer { deflateEnd(&stream) }
        var output = [UInt8](repeating: 0, count: bytes.count + 1_024)
        var input = bytes
        let produced: Int = input.withUnsafeMutableBufferPointer { source in
            output.withUnsafeMutableBufferPointer { target in
                stream.next_in = source.baseAddress
                stream.avail_in = uInt(source.count)
                stream.next_out = target.baseAddress
                stream.avail_out = uInt(target.count)
                _ = zlib.deflate(&stream, Z_FINISH)
                return target.count - Int(stream.avail_out)
            }
        }
        return Array(output.prefix(produced))
    }

    /// A ZIP archive with the given members (`deflate` selects method 8); sizes and CRCs are exact.
    static func zip(_ entries: [(name: String, data: [UInt8], deflate: Bool)], flags: Int = 0) -> Data {
        func le(_ value: Int, _ width: Int) -> [UInt8] { (0..<width).map { UInt8(truncatingIfNeeded: value >> ($0 * 8)) } }
        var body: [UInt8] = []
        var directory: [UInt8] = []
        for entry in entries {
            let payload = entry.deflate ? rawDeflate(entry.data) : entry.data
            let crc = entry.data.withUnsafeBufferPointer { UInt32(zlib.crc32(0, $0.baseAddress, uInt($0.count))) }
            let name = Array(entry.name.utf8)
            let method = entry.deflate ? 8 : 0
            let offset = body.count
            body += le(0x04034b50, 4) + le(20, 2) + le(flags, 2) + le(method, 2) + le(0, 2) + le(33, 2)
            body += le(Int(crc), 4) + le(payload.count, 4) + le(entry.data.count, 4) + le(name.count, 2) + le(0, 2) + name + payload
            directory += le(0x02014b50, 4) + le(20, 2) + le(20, 2) + le(flags, 2) + le(method, 2) + le(0, 2) + le(33, 2)
            directory += le(Int(crc), 4) + le(payload.count, 4) + le(entry.data.count, 4) + le(name.count, 2)
            directory += le(0, 2) + le(0, 2) + le(0, 2) + le(0, 2) + le(0, 4) + le(offset, 4) + name
        }
        let end = le(0x06054b50, 4) + le(0, 2) + le(0, 2) + le(entries.count, 2) + le(entries.count, 2)
            + le(directory.count, 4) + le(body.count, 4) + le(0, 2)
        return Data(body + directory + end)
    }

    /// Every failure an adapter may report; anything else (a trap, another error type) fails the test.
    static func expectBounded(_ label: String, _ body: () throws -> Void) {
        do { try body() }
        catch is PreviewFailure {}
        catch { Issue.record("\(label): unexpected error \(error)") }
    }
}

/// Data tests keep their local name while sharing the bounded, thread-safe read recorder.
typealias DataRecordingSource = RecordingByteSource
